-- 027_triggers_01_order_notifications.sql
--
-- Notifications are generated by the database when an order changes state,
-- never by the client. The Flutter app had four hard-coded notification
-- strings and no server source at all.

create or replace function engagement.notify_order_status()
returns trigger
language plpgsql
security definer
set search_path = ''
as $fn$
declare
  v_user uuid;
  v_dedupe text;
begin
  if tg_op = 'UPDATE' and new.status is not distinct from old.status then
    return new;
  end if;

  select user_id into v_user from orders.orders where id = new.id;

  -- one notification per (order, status). dedupe_key makes a repeat
  -- transition a no-op instead of a duplicate.
  v_dedupe := 'order:' || new.id::text || ':' || new.status;

  insert into engagement.notifications
    (user_id, type, title_ar, title_en, body_ar, body_en,
     payload, related_entity_type, related_entity_id, dedupe_key)
  values (
    v_user,
    'order_status',
    'تحديث حالة الطلب ' || new.order_number,
    'Order ' || new.order_number || ' updated',
    'حالة طلبك الآن: ' || new.status,
    'Your order status is now: ' || new.status,
    jsonb_build_object('order_id', new.id, 'order_number', new.order_number,
                       'status', new.status, 'total', new.grand_total,
                       'branch_id', new.branch_id),
    'order',
    new.id,
    v_dedupe
  )
  on conflict (user_id, dedupe_key) do nothing;

  return new;
end;
$fn$;

comment on function engagement.notify_order_status() is
  'After order status change: create one in-app notification. dedupe_key prevents duplicates.';

drop trigger if exists tr_orders_notify on orders.orders;
create trigger tr_orders_notify
  after update of status on orders.orders
  for each row execute function engagement.notify_order_status();

-- ---------------------------------------------------------------------------
-- Loyalty notification when points are awarded or spent.
-- ---------------------------------------------------------------------------
create or replace function engagement.notify_loyalty()
returns trigger
language plpgsql
security definer
set search_path = ''
as $fn$
declare
  v_dedupe text;
begin
  v_dedupe := 'loyalty:' || new.user_id::text || ':' || new.id::text;

  insert into engagement.notifications
    (user_id, type, title_ar, title_en, body_ar, body_en,
     payload, related_entity_type, related_entity_id, dedupe_key)
  values (
    new.user_id,
    'loyalty',
    case when new.points > 0 then 'ربحت نقاط' else 'استخدمت نقاط' end,
    case when new.points > 0 then 'Points earned' else 'Points redeemed' end,
    case when new.points > 0
      then 'ربحت ' || new.points || ' نقطة. رصيدك ' || new.balance_after
      else 'استخدمت ' || abs(new.points) || ' نقطة. رصيدك ' || new.balance_after end,
    case when new.points > 0
      then 'You earned ' || new.points || ' points. Balance: ' || new.balance_after
      else 'You used ' || abs(new.points) || ' points. Balance: ' || new.balance_after end,
    jsonb_build_object('points', new.points, 'balance_after', new.balance_after, 'reason', new.reason),
    'loyalty', new.id, v_dedupe
  )
  on conflict (user_id, dedupe_key) do nothing;

  return new;
end;
$fn$;

drop trigger if exists tr_loyalty_notify on loyalty.loyalty_transactions;
create trigger tr_loyalty_notify
  after insert on loyalty.loyalty_transactions
  for each row execute function engagement.notify_loyalty();

-- ---------------------------------------------------------------------------
-- Grant execute on the RPC surface to client roles. Each one has an internal
-- permission check, so the grant is only about reachability.
-- ---------------------------------------------------------------------------
grant execute on function
  core.active_branches(),
  catalog.resolve_effective_price(uuid, uuid, uuid[]),
  catalog.search_products(text, uuid, uuid, numeric, numeric, text, integer, integer),
  catalog.get_best_sellers(uuid, interval, integer),
  catalog.get_featured(uuid, integer),
  orders.get_or_create_cart(uuid),
  orders.upsert_cart_item(uuid, uuid, integer, text, uuid[]),
  orders.remove_cart_item(uuid),
  orders.get_cart_summary(uuid),
  orders.place_order(uuid, text, text, uuid, text, text),
  orders.cancel_order(uuid, text),
  marketing.validate_coupon(text, numeric, uuid),
  loyalty.redeem_reward(uuid, uuid),
  engagement.mark_notifications_read(uuid[])
  to authenticated;

-- Public catalogue reads stay anonymous.
grant execute on function
  core.active_branches(),
  catalog.resolve_effective_price(uuid, uuid, uuid[]),
  catalog.search_products(text, uuid, uuid, numeric, numeric, text, integer, integer),
  catalog.get_best_sellers(uuid, interval, integer),
  catalog.get_featured(uuid, integer)
  to anon;

-- update_order_status is staff-only.
grant execute on function orders.update_order_status(uuid, text, text) to authenticated;

-- inventory.adjust_stock stays service_role only; it is an admin panel call.
revoke execute on function inventory.adjust_stock(uuid, uuid, integer, text, text, uuid) from anon, authenticated;
grant execute on function inventory.adjust_stock(uuid, uuid, integer, text, text, uuid) to service_role;

-- ai.* is unreachable from every client role.
revoke execute on all functions in schema ai from anon, authenticated;
revoke all on schema ai from anon, authenticated;